jsonTools.init:
function init(eli) {
  var ACCENT = "#c9a227";
  var BUG = "#c9a227", BUG_DK = "#8b6914";
  var IMP = "#6366f1", IMP_DK = "#4338ca";

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _toast(m, t) { if (typeof showToast === "function") showToast(m, t || "info"); }
  function _ls(k) { try { return (eli.compat && eli.compat.lsGet ? (eli.compat.lsGet(k) || "") : ""); } catch (_) { return ""; } }
  function _mount() { return document.getElementById("_eli3_dashboard_root"); }

  var _filter = "all"; // all | bug | improvement
  var _rows = null;     // cached last fetch

  function _ghConfig() {
    return {
      repo: _ls("eli_github_repo") || "apndrewn/eli-data",
      branch: _ls("eli_github_branch") || "main",
      pat: _ls("eli_user_github_pat") || "",
    };
  }

  // Fetch the submissions directory listing, then each file's JSON. Newest
  // first (filenames are <epochMs>_<rand>.json). Capped so a big backlog
  // doesn't fire hundreds of requests.
  function _fetchSubmissions() {
    var cfg = _ghConfig();
    var headers = { "Accept": "application/vnd.github+json", "X-GitHub-Api-Version": "2022-11-28" };
    if (cfg.pat) headers["Authorization"] = "Bearer " + cfg.pat;
    var listUrl = "https://api.github.com/repos/" + cfg.repo +
      "/contents/feedback/submissions?ref=" + encodeURIComponent(cfg.branch) + "&t=" + Date.now();
    return fetch(listUrl, { headers: headers }).then(function (r) {
      if (r.status === 404) return { _empty: true };
      if (!r.ok) return r.text().then(function (t) { throw new Error("GitHub " + r.status + " · " + t.slice(0, 120)); });
      return r.json();
    }).then(function (list) {
      if (list && list._empty) return [];
      if (!Array.isArray(list)) return [];
      var files = list.filter(function (f) { return f && f.type === "file" && /\.json$/i.test(f.name); })
        .sort(function (a, b) { return String(b.name).localeCompare(String(a.name)); })
        .slice(0, 80);
      return Promise.all(files.map(function (f) {
        return fetch(f.download_url + (f.download_url.indexOf("?") >= 0 ? "&" : "?") + "t=" + Date.now())
          .then(function (r) { return r.ok ? r.json() : null; })
          .then(function (json) { return json ? { _name: f.name, data: json } : null; })
          .catch(function () { return null; });
      }));
    }).then(function (arr) { return (arr || []).filter(Boolean); });
  }

  function _fmtWhen(iso) {
    if (!iso) return "";
    try { return new Date(iso).toLocaleString(undefined, { dateStyle: "medium", timeStyle: "short" }); }
    catch (_) { return String(iso); }
  }

  function _card(entry) {
    var d = entry.data || {};
    var isImp = d.type === "improvement";
    var c = isImp ? IMP : BUG, cd = isImp ? IMP_DK : BUG_DK;
    var badge = isImp ? "💡 IMPROVEMENT / NEW TOOL" : "🐞 BUG";
    var u = (d.context && d.context.user) || {};
    var who = u.name || u.email || "(unknown)";
    var ctx = d.context || {};
    var events = Array.isArray(ctx.events) ? ctx.events : [];
    var ctxBits = [];
    if (ctx.kernelVersion) ctxBits.push("kernel " + _esc(ctx.kernelVersion));
    if (u.email) ctxBits.push(_esc(u.email));
    if (ctx.selfTest) ctxBits.push("selfTest " + _esc(ctx.selfTest));
    if (events.length) ctxBits.push(events.length + " log entries");
    return '' +
      '<div style="background:#fff; border:1px solid #e2e8f0; border-left:4px solid ' + c + '; border-radius:10px; padding:14px 16px; margin-bottom:12px; box-shadow:0 1px 3px rgba(15,23,42,.05);">' +
        '<div style="display:flex; align-items:center; gap:10px; margin-bottom:6px;">' +
          '<span style="font:800 9px/1 Inter,sans-serif; letter-spacing:.08em; color:#fff; background:' + c + '; padding:4px 9px; border-radius:5px;">' + badge + '</span>' +
          '<span style="flex:1"></span>' +
          '<span style="font:600 10.5px/1 Inter,sans-serif; color:#94a3b8;">' + _esc(_fmtWhen(d.submittedAt)) + '</span>' +
        '</div>' +
        '<div style="font:800 14px/1.3 Inter,sans-serif; color:#0f172a; margin-bottom:4px;">' + _esc(d.title || "(untitled)") + '</div>' +
        '<div style="font:600 11px/1 Inter,sans-serif; color:' + cd + '; margin-bottom:8px;">From ' + _esc(who) + '</div>' +
        '<div style="font:500 12.5px/1.55 Inter,sans-serif; color:#1e293b; white-space:pre-wrap; word-break:break-word;">' + _esc(d.description || "(no description)") + '</div>' +
        (ctxBits.length
          ? '<details style="margin-top:10px;"><summary style="cursor:pointer; font:700 9.5px/1 Inter,sans-serif; letter-spacing:.06em; text-transform:uppercase; color:#94a3b8;">Context</summary>' +
              '<div style="margin-top:6px; font:500 10.5px/1.5 Inter,sans-serif; color:#64748b;">' + ctxBits.join(" · ") + '</div>' +
              (events.length ? '<pre style="margin-top:8px; max-height:200px; overflow:auto; background:#f8fafc; border:1px solid #e2e8f0; border-radius:6px; padding:8px; font:500 10px/1.4 ui-monospace,Menlo,monospace; color:#475569; white-space:pre-wrap;">' + _esc(JSON.stringify(events, null, 1)) + '</pre>' : '') +
            '</details>'
          : '') +
      '</div>';
  }

  function _renderBody(bodyEl, state) {
    if (state === "loading") {
      bodyEl.innerHTML = '<div style="text-align:center; padding:48px 0; color:#94a3b8; font:600 12px/1.5 Inter,sans-serif;">⏳ Loading submissions from GitHub…</div>';
      return;
    }
    if (state && state.error) {
      bodyEl.innerHTML = '<div style="background:#fef2f2; border:1px solid #fecaca; border-radius:10px; padding:16px; color:#991b1b; font:600 12px/1.5 Inter,sans-serif;">' +
        '⚠️ Couldn\'t load submissions.<br><span style="font-weight:500; color:#b91c1c;">' + _esc(state.error) + '</span>' +
        '<div style="margin-top:8px; font-weight:500; color:#7f1d1d;">If the repo is private, add a GitHub PAT in Settings → Advanced. (Unauthenticated GitHub API is limited to ~60 requests/hour.)</div>' +
      '</div>';
      return;
    }
    var rows = (_rows || []).filter(function (e) {
      if (_filter === "all") return true;
      return (e.data && e.data.type) === _filter;
    });
    if (!rows.length) {
      bodyEl.innerHTML = '<div style="text-align:center; padding:48px 16px; color:#94a3b8; font:600 12.5px/1.6 Inter,sans-serif;">' +
        (_rows && _rows.length ? 'No ' + (_filter === "bug" ? "bug reports" : "suggestions") + ' in this view.' : 'No submissions yet.') +
        '</div>';
      return;
    }
    bodyEl.innerHTML = rows.map(_card).join("");
  }

  function _counts() {
    var b = 0, i = 0;
    (_rows || []).forEach(function (e) { if (e.data && e.data.type === "improvement") i++; else b++; });
    return { bug: b, imp: i, all: (_rows || []).length };
  }

  function _pill(label, key, active) {
    return '<button data-fi-filter="' + key + '" style="padding:6px 12px; border-radius:999px; cursor:pointer; ' +
      'font:700 10.5px/1 Inter,sans-serif; border:1.5px solid ' + (active ? ACCENT : "#cbd5e1") + '; ' +
      'background:' + (active ? "linear-gradient(180deg,#fffdf4,#fbf0c8)" : "#fff") + '; color:' + (active ? "#6b4f06" : "#475569") + ';">' + label + '</button>';
  }

  function _render() {
    var m = _mount();
    if (!m) { _toast("Dashboard root missing", "err"); return; }
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedFeedbackInbox"); } catch (_) {}
    m.innerHTML = "";
    var root = document.createElement("div");
    // #_eli3_dashboard_root is display:flex;flex-direction:row — without
    // width/flex the panel shrinks to its content (~half width) and the
    // dashboard shows through. Fill the row.
    root.style.cssText = "background:#f1f5f9; min-height:100%; width:100%; flex:1 0 auto; min-width:0; box-sizing:border-box; font:500 13px/1.45 'Inter','Segoe UI',sans-serif; color:#0f172a;";
    root.innerHTML =
      '<div style="background:linear-gradient(180deg,#0d1b2a,#1b263b); border-bottom:3px solid ' + ACCENT + '; padding:14px 20px; display:flex; align-items:center; gap:12px; position:sticky; top:0; z-index:5;">' +
        '<button data-act="back" title="Back" style="border:1px solid rgba(255,255,255,.25); background:rgba(255,255,255,.08); color:#e2e8f0; border-radius:6px; padding:4px 10px; cursor:pointer; font-size:14px;">←</button>' +
        '<span style="font-size:16px;">📥</span>' +
        '<div style="font:800 15px/1 Inter,sans-serif; color:#fff; letter-spacing:.02em;">Feedback Inbox</div>' +
        '<div style="flex:1"></div>' +
        '<button data-act="refresh" style="border:1px solid ' + ACCENT + '; background:rgba(201,162,39,.18); color:#f2d866; border-radius:6px; padding:6px 12px; cursor:pointer; font:800 10px/1 Inter,sans-serif; letter-spacing:.06em; text-transform:uppercase;">↻ Refresh</button>' +
      '</div>' +
      '<div data-slot="bar" style="padding:14px 20px 0; max-width:760px; margin:0 auto; display:flex; gap:8px; align-items:center; flex-wrap:wrap;"></div>' +
      '<div data-slot="body" style="padding:14px 20px 28px; max-width:760px; margin:0 auto;"></div>';
    m.appendChild(root);
    var bar = root.querySelector("[data-slot='bar']");
    var bodyEl = root.querySelector("[data-slot='body']");
    root.querySelector("[data-act='back']").onclick = function () {
      if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
    };
    function _paintBar() {
      var c = _counts();
      bar.innerHTML =
        _pill("All (" + c.all + ")", "all", _filter === "all") +
        _pill("🐞 Bugs (" + c.bug + ")", "bug", _filter === "bug") +
        _pill("💡 Suggestions (" + c.imp + ")", "improvement", _filter === "improvement");
      Array.prototype.slice.call(bar.querySelectorAll("[data-fi-filter]")).forEach(function (b) {
        b.onclick = function () { _filter = b.getAttribute("data-fi-filter"); _paintBar(); _renderBody(bodyEl); };
      });
    }
    function _load() {
      _renderBody(bodyEl, "loading");
      bar.innerHTML = "";
      _fetchSubmissions().then(function (rows) {
        _rows = rows;
        _paintBar();
        _renderBody(bodyEl);
      }).catch(function (err) {
        _rows = null;
        _renderBody(bodyEl, { error: (err && err.message) || "Request failed" });
      });
    }
    root.querySelector("[data-act='refresh']").onclick = _load;
    _load();
  }

  eli.register({ tile: { app_feedback_inbox: _render } });
  eli.log.event("tool", "feedback_inbox_initialized", {});
}
